        changed = self.replace_once(self.current,'format!("{}{}", BASE_DDL, crate::ancestry_index::DDL)',
                                    'format!("{}", BASE_DDL)')
        with self.assertRaisesRegex(ValueError,'durable V2 schema composition'): self.extract(changed)

